<span class="line"><span style="color:#005CC5">      "type"</span><span style="color:#24292E">:</span><span style="color:#032F62">"IMPRESSION"</span><span style="color:#24292E">,</span></span>
<span class="line"><span style="color:#005CC5">      "impressionToken"</span><span style="color:#24292E">:</span><span style="color:#032F62">"signed-token"</span><span style="color:#24292E">,</span></span>
<span class="line"><span style="color:#005CC5">      "eventTime"</span><span style="color:#24292E">:</span><span style="color:#032F62">"2026-07-13T17:00:00Z"</span><span style="color:#24292E">,</span></span>
<span class="line"><span style="color:#005CC5">      "client"</span><span style="color:#24292E">:{</span><span style="color:#005CC5">"sdkVersion"</span><span style="color:#24292E">:</span><span style="color:#032F62">"web@4"</span><span style="color:#24292E">,</span><span style="color:#005CC5">"sequence"</span><span style="color:#24292E">:</span><span style="color:#005CC5">881</span><span style="color:#24292E">}</span></span>
