<span class="line"><span style="color:#24292E">        reasons.append(</span><span style="color:#032F62">"AMOUNT_OVER_LIMIT"</span><span style="color:#24292E">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49">    if</span><span style="color:#24292E"> transaction.country </span><span style="color:#D73A49">in</span><span style="color:#24292E"> account.blocked_countries:</span></span>
<span class="line"><span style="color:#24292E">        reasons.append(</span><span style="color:#032F62">"BLOCKED_COUNTRY"</span><span style="color:#24292E">)</span></span>
<span class="line"></span>
<span class="line"><span style="color:#D73A49">    if</span><span style="color:#24292E"> transaction.failed_attempts_5m </span><span style="color:#D73A49">>=</span><span style="color:#005CC5"> 5</span><span style="color:#24292E">:</span></span>
<span class="line"><span style="color:#24292E">        reasons.append(</span><span style="color:#032F62">"VELOCITY_5M"</span><span style="color:#24292E">)</span></span>
<span class="line"></span>
