INSERT INTO posts (id, path, title, description, venue, tags, body_markdown, body_html, headings, created_at, timestamp_precision, updated_at, is_public) VALUES ('d5bf8eb5-8315-49f8-a063-9989ded8c221', 'system-design/stock-exchange-matching-engine', '系统设计：股票交易所撮合引擎（Matching Engine）', '设计一个 stock exchange 的核心撮合引擎——聚焦 low latency、fairness、determinism。从「面试里该问什么」开始拆解。', NULL, '["system-design","interview","learning"]', '', '', '[{"depth":2,"slug":"问题定位","text":"问题定位"},{"depth":2,"slug":"第一步该问哪些-clarifying-questions","text":"第一步：该问哪些 clarifying questions？"},{"depth":3,"slug":"元原则只问会改变设计的问题","text":"元原则：只问会「改变设计」的问题"},{"depth":3,"slug":"高杠杆问题按优先级","text":"高杠杆问题（按优先级）"},{"depth":3,"slug":"低价值问题别在开场问","text":"低价值问题（别在开场问）"},{"depth":2,"slug":"第二步锁定-assumptions","text":"第二步：锁定 Assumptions"},{"depth":3,"slug":"关于-latency-的三档重要","text":"关于 Latency 的三档（重要）"},{"depth":2,"slug":"第三步functional--non-functional-requirements","text":"第三步：Functional / Non-functional Requirements"},{"depth":3,"slug":"functional-requirements","text":"Functional Requirements"},{"depth":3,"slug":"non-functional-requirements","text":"Non-functional Requirements"},{"depth":3,"slug":"-focus选一条主线深挖","text":"⭐ Focus：选一条主线深挖"},{"depth":3,"slug":"关键取舍撮合引擎是-cp-系统","text":"关键取舍：撮合引擎是 CP 系统"},{"depth":2,"slug":"第四步api--interface-design","text":"第四步：API / Interface Design"},{"depth":3,"slug":"分层对外-api-不敏感引擎内部才敏感","text":"分层：对外 API 不敏感，引擎内部才敏感"},{"depth":3,"slug":"两个-apiwrite-path--read-path","text":"两个 API：write path + read path"},{"depth":2,"slug":"第五步high-level-architecture","text":"第五步：High-level Architecture"},{"depth":3,"slug":"方法论用-data-flow-来发现架构","text":"方法论：用 data flow 来「发现」架构"},{"depth":3,"slug":"sequencer-是什么","text":"Sequencer 是什么？"},{"depth":3,"slug":"matching-engine单线程-singleton不是-worker-pool","text":"Matching engine：单线程 singleton，不是 worker pool"},{"depth":3,"slug":"数据流图","text":"数据流图"},{"depth":3,"slug":"如何-scale","text":"如何 Scale"},{"depth":2,"slug":"待续","text":"待续"}]', '2026-05-30T00:00:00.000Z', 'd